using System;
using System.Collections.Generic;
using System.Text;

namespace Domain.Entities
{ //A history and log of events and modifications in Recoil.
    public class AuditLog
    {
        public Guid Id { get; set; }

        public DateTime CreatedAt { get; set; }

        public Guid CreatedBy { get; set; }

        //Correlation ID of the request that caused this change, if available. This is a GUID generated by the client and passed through the API gateway to the backend, so it can be used to correlate multiple changes made in a single request.
        public Guid CorrelationId { get; set; }

        //Name of the affecxted entity type, e.g. "Incident", "CheckDataPoint", etc.

        public string EntityType { get; set; }

        //Primary key of the affected entity, e.g. 12345, "abcde", etc.
        public string EntityId { get; set; }

        //JSON snapshot of the affected entity's scalar properties, excluding any marked with [NotAudited].
        public string Snapshot { get; set; }

        //Old snapshot of the affected entity's scalar properties, excluding any marked with [NotAudited].
        public string? OldSnapshot { get; set; }

        //Human-readable summary of the change, e.g. "Changed status from 'Open' to 'Closed'".
        public string? ChangeSummary { get; set; }

        //IP address of the user who made the change, if available.
        public string? IpAddress { get; set; }


    }
}
